import json
p='/workspace/run_trace/galaxy_tool_run_003/validation_response.json'
d=json.load(open(p))
# find state? print keys and maybe model
for k,v in d.items():
    if k in ['inputs','errors','help']:
        continue
    print(k, type(v), str(v)[:500])
# search inputs for name source/own_file
def walk(o, path=''):
    if isinstance(o,dict):
        if o.get('name') in ['source','own_file','type','analysis_type_selector','rg_selector','sam_options_selector']:
            print('FIELD', path, o.get('name'), 'value=', o.get('value'), 'default=', o.get('default_value'))
        for k,v in o.items(): walk(v, path+'/'+str(k))
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v, path+'/'+str(i))
walk(d.get('inputs'))
PY"

